<script setup>import MButton from '../../../components/mds/MButton.vue';import MEmptyState from '../../../components/mds/MEmptyState.vue';import MMobileTopBar from '../../../components/mds/MMobileTopBar.vue';import MTag from '../../../components/mds/MTag.vue';defineProps({rows:{type:Array,default:()=>[]},safeAreaStyle:Object,canViewAudit:Boolean,canViewVisibility:Boolean,canCreate:Boolean,canEdit:Function,canDelete:Function});const emit=defineEmits(['back','audit','visibility','create','edit','delete']);</script>
<template><section class="mds-mobile-app flex h-[100dvh] min-w-0 flex-col overflow-hidden bg-[var(--mds-bg)]" :style="safeAreaStyle"><MMobileTopBar title="Quản trị hệ thống" @back="emit('back')"><template #actions><MButton v-if="canViewAudit" variant="ghost" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('audit')">Audit</MButton><MButton v-if="canCreate" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('create')">Thêm</MButton></template></MMobileTopBar><main class="min-h-0 flex-1 overflow-y-auto pb-[var(--mds-mobile-safe-bottom)]"><div v-if="canViewVisibility" class="mds-mobile-gutter-x flex min-h-[64px] items-center border-b border-[var(--mds-border-light)]"><MButton variant="ghost" class="w-full justify-start [&]:h-[var(--mds-mobile-touch-target)]" @click="emit('visibility')">Cấu hình hiển thị trường</MButton></div><div v-if="rows.length" class="divide-y divide-[var(--mds-border-light)]"><article v-for="user in rows" :key="user.id" class="mds-mobile-gutter-x py-3"><div class="flex items-start justify-between gap-3"><div class="min-w-0"><strong class="block truncate text-[14px]">{{ user.fullName || user.username }}</strong><p class="mt-1 truncate text-[13px] text-[var(--mds-text-secondary)]">{{ user.username }} · {{ user.email || 'Chưa có email' }}</p></div><MTag :color="user.active?'success':'neutral'">{{ user.active?'Hoạt động':'Khóa' }}</MTag></div><div class="mt-2 flex items-center justify-between gap-2"><MTag color="brand">{{ user.roleLabel }}</MTag><div class="flex gap-2"><MButton v-if="canEdit?.(user)" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)]" @click="emit('edit',user)">Sửa</MButton><MButton v-if="canDelete?.(user)" variant="link" class="[&]:h-[var(--mds-mobile-touch-target)] [&]:text-[var(--mds-danger)]" @click="emit('delete',user)">Xóa</MButton></div></div></article></div><MEmptyState v-else title="Chưa có người dùng" description="Máy chủ chưa trả người dùng được phép xem."/></main></section></template>
